// Generates src/generated/ from JSON Schema exported by packages/domain.
// P0: the domain model is empty, so this writes an empty module. P1 replaces the body with
// `uv run python -m fl_domain.schema` → json-schema-to-typescript.
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const out = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "generated");
mkdirSync(out, { recursive: true });
writeFileSync(
  join(out, "index.ts"),
  "// GENERATED by packages/ts-types/scripts/generate.mjs. Do not edit.\nexport {};\n",
);
console.log(`ts-types: wrote ${out}`);
